/*
 * VECTOR_ARTIFACT_FOUNDATION_5741
 *
 * Local PDF / DOCX / XLSX generation.
 * Generated bytes are encrypted with Vector's existing VEC1 storage.
 */

import crypto
  from "node:crypto";

import {
  db,
  initializeDatabase
} from "./db";

import {
  cleanFilename,
  extensionFor,
  sha256,
  writeEncryptedFile
} from "./project-files";

import {
  restorePrivateValues
} from "./privacy-vault";


const MIME_TYPES = {
  pdf:
    "application/pdf",

  docx:
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",

  xlsx:
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
};


function safeScopePart(value) {
  return String(
    value ||
    "unknown"
  ).replace(
    /[^A-Za-z0-9_-]/g,
    "_"
  );
}


function artifactScope(userId) {
  return (
    `artifact-${safeScopePart(
      userId
    )}`
  );
}


function normalizeFormat(value) {
  const format =
    String(
      value ||
      ""
    )
      .trim()
      .toLowerCase();

  if (
    ![
      "pdf",
      "docx",
      "xlsx"
    ].includes(
      format
    )
  ) {
    throw new Error(
      "Artifact format must be pdf, docx or xlsx."
    );
  }

  return format;
}


function ensureFilename(
  filename,
  format
) {
  let name =
    cleanFilename(
      filename ||
      `vector-artifact.${format}`
    );

  const extension =
    `.${format}`;

  if (
    !name
      .toLowerCase()
      .endsWith(
        extension
      )
  ) {
    name +=
      extension;
  }

  return name;
}


function cleanDocumentText(value) {
  return String(
    value ||
    ""
  )
    .replace(
      /\r\n?/g,
      "\n"
    )
    .trim();
}


function documentLines(
  title,
  content
) {
  const result = [];

  if (
    String(
      title ||
      ""
    ).trim()
  ) {
    result.push({
      kind:
        "title",

      text:
        String(
          title
        ).trim()
    });
  }

  for (
    const rawLine
    of cleanDocumentText(
      content
    ).split(
      "\n"
    )
  ) {
    const line =
      rawLine.trimEnd();

    if (!line.trim()) {
      result.push({
        kind:
          "blank",

        text:
          ""
      });

      continue;
    }

    const heading =
      line.match(
        /^(#{1,4})\s+(.+)$/
      );

    if (heading) {
      result.push({
        kind:
          `h${heading[1].length}`,

        text:
          heading[2].trim()
      });

      continue;
    }

    const bullet =
      line.match(
        /^\s*[-*]\s+(.+)$/
      );

    if (bullet) {
      result.push({
        kind:
          "bullet",

        text:
          bullet[1].trim()
      });

      continue;
    }

    const numbered =
      line.match(
        /^\s*\d+[.)]\s+(.+)$/
      );

    if (numbered) {
      result.push({
        kind:
          "number",

        text:
          numbered[1].trim()
      });

      continue;
    }

    result.push({
      kind:
        "paragraph",

      text:
        line.trim()
    });
  }

  return result;
}



/*
 * VECTOR_ARTIFACT_COMPOSER_V2_5744
 *
 * Structured document composer used by PDF and DOCX.
 * Input remains lightweight Markdown so all providers can use it.
 */

function composerInlineRuns(value) {
  const input =
    String(
      value ||
      ""
    );

  const result = [];

  const pattern =
    /(\*\*[^*]+\*\*|__[^_]+__|`[^`]+`|\*[^*]+\*|_[^_]+_)/g;

  let cursor = 0;
  let match;

  while (
    (
      match =
        pattern.exec(
          input
        )
    )
  ) {
    if (
      match.index >
      cursor
    ) {
      result.push({
        text:
          input.slice(
            cursor,
            match.index
          ),

        bold:
          false,

        italic:
          false,

        code:
          false
      });
    }

    const token =
      match[0];

    if (
      token.startsWith(
        "**"
      ) &&
      token.endsWith(
        "**"
      )
    ) {
      result.push({
        text:
          token.slice(
            2,
            -2
          ),

        bold:
          true,

        italic:
          false,

        code:
          false
      });

    } else if (
      token.startsWith(
        "__"
      ) &&
      token.endsWith(
        "__"
      )
    ) {
      result.push({
        text:
          token.slice(
            2,
            -2
          ),

        bold:
          true,

        italic:
          false,

        code:
          false
      });

    } else if (
      token.startsWith(
        "`"
      ) &&
      token.endsWith(
        "`"
      )
    ) {
      result.push({
        text:
          token.slice(
            1,
            -1
          ),

        bold:
          false,

        italic:
          false,

        code:
          true
      });

    } else {
      result.push({
        text:
          token.slice(
            1,
            -1
          ),

        bold:
          false,

        italic:
          true,

        code:
          false
      });
    }

    cursor =
      match.index +
      token.length;
  }

  if (
    cursor <
    input.length
  ) {
    result.push({
      text:
        input.slice(
          cursor
        ),

      bold:
        false,

      italic:
        false,

      code:
        false
    });
  }

  if (
    result.length ===
    0
  ) {
    result.push({
      text:
        input,

      bold:
        false,

      italic:
        false,

      code:
        false
    });
  }

  return result;
}


function composerPlainText(value) {
  return composerInlineRuns(
    value
  )
    .map(
      (run) =>
        run.text
    )
    .join("");
}


function composerBlocks(
  title,
  content
) {
  const blocks = [];


  const cleanTitle =
    String(
      title ||
      ""
    ).trim();


  if (
    cleanTitle
  ) {
    blocks.push({
      kind:
        "title",

      text:
        cleanTitle
    });
  }


  const lines =
    cleanDocumentText(
      content
    ).split(
      "\n"
    );


  let firstMeaningful =
    true;

  let numberIndex =
    0;


  function tableCells(
    value
  ) {
    let row =
      String(
        value ||
        ""
      ).trim();


    if (
      row.startsWith(
        "|"
      )
    ) {
      row =
        row.slice(
          1
        );
    }


    if (
      row.endsWith(
        "|"
      )
    ) {
      row =
        row.slice(
          0,
          -1
        );
    }


    return row
      .split(
        "|"
      )
      .map(
        (
          cell
        ) =>
          cell.trim()
      );
  }


  function tableSeparator(
    value
  ) {
    const cells =
      tableCells(
        value
      );


    return (
      cells.length >
        0 &&
      cells.every(
        (
          cell
        ) =>
          /^:?-{3,}:?$/.test(
            cell.replace(
              /\s+/g,
              ""
            )
          )
      )
    );
  }


  for (
    let index = 0;
    index <
      lines.length;
    index += 1
  ) {
    const raw =
      lines[
        index
      ];


    const line =
      raw.trimEnd();


    const trimmed =
      line.trim();


    if (
      !trimmed
    ) {
      blocks.push({
        kind:
          "blank",

        text:
          ""
      });

      continue;
    }


    /*
     * VECTOR_PDF_CODE_BLOCKS_576
     */
    const fence =
      trimmed.match(
        /^```([A-Za-z0-9_+.\-]*)\s*$/
      );


    if (
      fence
    ) {
      const language =
        String(
          fence[1] ||
          ""
        ).trim();


      const codeLines =
        [];


      index += 1;


      while (
        index <
          lines.length &&
        !/^```\s*$/.test(
          lines[
            index
          ].trim()
        )
      ) {
        codeLines.push(
          lines[
            index
          ]
        );

        index += 1;
      }


      blocks.push({
        kind:
          "codeblock",

        language,

        text:
          codeLines.join(
            "\n"
          )
      });


      firstMeaningful =
        false;

      numberIndex =
        0;

      continue;
    }


    if (
      /^[-*_]{3,}$/.test(
        trimmed
      )
    ) {
      blocks.push({
        kind:
          "divider",

        text:
          ""
      });


      firstMeaningful =
        false;

      numberIndex =
        0;

      continue;
    }


    const heading =
      trimmed.match(
        /^(#{1,4})\s+(.+)$/
      );


    if (
      heading
    ) {
      const headingText =
        heading[2].trim();


      if (
        firstMeaningful &&
        cleanTitle &&
        composerPlainText(
          headingText
        ).trim().toLowerCase() ===
        composerPlainText(
          cleanTitle
        ).trim().toLowerCase()
      ) {
        firstMeaningful =
          false;

        continue;
      }


      blocks.push({
        kind:
          `h${heading[1].length}`,

        text:
          headingText
      });


      firstMeaningful =
        false;

      numberIndex =
        0;

      continue;
    }


    const quote =
      trimmed.match(
        /^>\s*(.+)$/
      );


    if (
      quote
    ) {
      blocks.push({
        kind:
          "callout",

        text:
          quote[1].trim()
      });


      firstMeaningful =
        false;

      numberIndex =
        0;

      continue;
    }


    /*
     * VECTOR_PDF_MARKDOWN_TABLES_576
     *
     * Detect:
     *
     * | Column | Column |
     * | ------ | ------ |
     * | Value  | Value  |
     */
    if (
      trimmed.includes(
        "|"
      ) &&
      index + 1 <
        lines.length &&
      tableSeparator(
        lines[
          index + 1
        ]
      )
    ) {
      const headers =
        tableCells(
          trimmed
        );


      const rows =
        [];


      index += 2;


      while (
        index <
        lines.length
      ) {
        const candidate =
          lines[
            index
          ].trim();


        if (
          !candidate ||
          !candidate.includes(
            "|"
          )
        ) {
          index -= 1;
          break;
        }


        rows.push(
          tableCells(
            candidate
          )
        );


        if (
          index ===
          lines.length -
            1
        ) {
          break;
        }


        index += 1;
      }


      blocks.push({
        kind:
          "table",

        headers,

        rows
      });


      firstMeaningful =
        false;

      numberIndex =
        0;

      continue;
    }


    const bullet =
      trimmed.match(
        /^[-*]\s+(.+)$/
      );


    if (
      bullet
    ) {
      blocks.push({
        kind:
          "bullet",

        text:
          bullet[1].trim()
      });


      firstMeaningful =
        false;

      continue;
    }


    const numbered =
      trimmed.match(
        /^(\d+)[.)]\s+(.+)$/
      );


    if (
      numbered
    ) {
      numberIndex +=
        1;


      blocks.push({
        kind:
          "number",

        number:
          numbered[1] ||
          String(
            numberIndex
          ),

        text:
          numbered[2].trim()
      });


      firstMeaningful =
        false;

      continue;
    }


    numberIndex =
      0;


    blocks.push({
      kind:
        "paragraph",

      text:
        trimmed
    });


    firstMeaningful =
      false;
  }


  return blocks;
}



/*
 * VECTOR_DOCX_COMPOSER_V3_577
 *
 * Semantic DOCX renderer using the shared document model.
 *
 * Features:
 *   - Artifact Intelligence plan
 *   - audience/archetype-aware document identity
 *   - running header
 *   - Page X of Y footer
 *   - H1-H4 hierarchy
 *   - keep-with-next headings
 *   - inline emphasis/code
 *   - callouts
 *   - lists
 *   - Markdown tables
 *   - repeating table header rows
 *   - fenced code blocks
 *   - metadata
 */
async function createDocx({
  title,
  content,
  artifactPlan = null
}) {
  const imported =
    await import(
      "docx"
    );


  const {
    Document,
    Packer,
    Paragraph,
    TextRun,
    HeadingLevel,
    AlignmentType,
    BorderStyle,
    Footer,
    Header,
    PageNumber,
    Table,
    TableRow,
    TableCell,
    WidthType
  } =
    imported;


  const palette = {
    ink:
      "26333A",

    muted:
      "77858C",

    accent:
      "37A786",

    accentDark:
      "123A42",

    accentDark2:
      "174F58",

    soft:
      "EAF7F2",

    code:
      "F4F6F6",

    border:
      "DCE4E6",

    white:
      "FFFFFF",

    zebra:
      "F7FAF9"
  };


  function label(
    value
  ) {
    return String(
      value ||
      ""
    )
      .replace(
        /_/g,
        " "
      )
      .replace(
        /\b\w/g,
        char =>
          char.toUpperCase()
      )
      .trim();
  }


  const archetype =
    String(
      artifactPlan
        ?.archetype ||
      "report"
    );


  const audience =
    String(
      artifactPlan
        ?.audience ||
      "general"
    );


  const archetypeLabel =
    label(
      archetype
    ) ||
    "Report";


  const audienceLabel =
    label(
      audience
    );


  const documentTitle =
    String(
      title ||
      "Vector document"
    );


  function runs(
    value,
    options = {}
  ) {
    return composerInlineRuns(
      value
    ).map(
      run =>
        new TextRun({
          text:
            run.text,

          bold:
            Boolean(
              options.bold ||
              run.bold
            ),

          italics:
            Boolean(
              options.italic ||
              run.italic
            ),

          font:
            options.font ||
            (
              run.code
                ? "Courier New"
                : "Aptos"
            ),

          size:
            options.size ||
            22,

          color:
            options.color ||
            palette.ink
        })
    );
  }


  function headingStyle(
    kind
  ) {
    const map = {
      h1: {
        heading:
          HeadingLevel.HEADING_1,

        size:
          34,

        color:
          palette.accentDark,

        before:
          300,

        after:
          120
      },

      h2: {
        heading:
          HeadingLevel.HEADING_2,

        size:
          29,

        color:
          palette.accentDark2,

        before:
          260,

        after:
          100
      },

      h3: {
        heading:
          HeadingLevel.HEADING_3,

        size:
          25,

        color:
          "2B5A60",

        before:
          220,

        after:
          80
      },

      h4: {
        heading:
          HeadingLevel.HEADING_4,

        size:
          22,

        color:
          "3B6468",

        before:
          180,

        after:
          70
      }
    };


    return map[
      kind
    ];
  }


  function tableCellParagraph(
    value,
    {
      header = false,
      fontSize = 19
    } = {}
  ) {
    return new Paragraph({
      children:
        runs(
          String(
            value ??
            ""
          ),
          {
            bold:
              header,

            size:
              fontSize,

            color:
              header
                ? palette.white
                : palette.ink
          }
        ),

      spacing: {
        before:
          40,

        after:
          40,

        line:
          260
      },

      keepLines:
        true,

      widowControl:
        true
    });
  }


  function renderTable(
    block
  ) {
    const headers =
      Array.isArray(
        block.headers
      )
        ? block.headers
        : [];


    const rows =
      Array.isArray(
        block.rows
      )
        ? block.rows
        : [];


    const columnCount =
      Math.max(
        1,
        headers.length,
        ...rows.map(
          row =>
            Array.isArray(
              row
            )
              ? row.length
              : 1
        )
      );


    const fontSize =
      columnCount <=
        3
        ? 19
        : columnCount <=
            5
          ? 17
          : columnCount <=
              7
            ? 15
            : 13;


    const percent =
      100 /
      columnCount;


    function cell(
      value,
      {
        header = false,
        zebra = false
      } = {}
    ) {
      return new TableCell({
        width: {
          size:
            percent,

          type:
            WidthType.PERCENTAGE
        },

        shading: {
          fill:
            header
              ? palette.accentDark
              : zebra
                ? palette.zebra
                : palette.white
        },

        margins: {
          top:
            90,

          bottom:
            90,

          left:
            110,

          right:
            110
        },

        children: [
          tableCellParagraph(
            value,
            {
              header,
              fontSize
            }
          )
        ]
      });
    }


    const tableRows = [];


    if (
      headers.length >
      0
    ) {
      tableRows.push(
        new TableRow({
          tableHeader:
            true,

          cantSplit:
            true,

          children:
            Array.from(
              {
                length:
                  columnCount
              },
              (
                _,
                index
              ) =>
                cell(
                  headers[
                    index
                  ] ??
                  "",
                  {
                    header:
                      true
                  }
                )
            )
        })
      );
    }


    rows.forEach(
      (
        row,
        rowIndex
      ) => {

        const source =
          Array.isArray(
            row
          )
            ? row
            : [
                row
              ];


        tableRows.push(
          new TableRow({
            cantSplit:
              true,

            children:
              Array.from(
                {
                  length:
                    columnCount
                },
                (
                  _,
                  index
                ) =>
                  cell(
                    source[
                      index
                    ] ??
                    "",
                    {
                      zebra:
                        rowIndex %
                          2 ===
                        1
                    }
                  )
              )
          })
        );

      }
    );


    return new Table({
      width: {
        size:
          100,

        type:
          WidthType.PERCENTAGE
      },

      borders: {
        top: {
          style:
            BorderStyle.SINGLE,

          size:
            4,

          color:
            palette.border
        },

        bottom: {
          style:
            BorderStyle.SINGLE,

          size:
            4,

          color:
            palette.border
        },

        left: {
          style:
            BorderStyle.SINGLE,

          size:
            4,

          color:
            palette.border
        },

        right: {
          style:
            BorderStyle.SINGLE,

          size:
            4,

          color:
            palette.border
        },

        insideHorizontal: {
          style:
            BorderStyle.SINGLE,

          size:
            3,

          color:
            palette.border
        },

        insideVertical: {
          style:
            BorderStyle.SINGLE,

          size:
            3,

          color:
            palette.border
        }
      },

      rows:
        tableRows
    });
  }


  function renderCodeBlock(
    block
  ) {
    const result = [];


    if (
      block.language
    ) {
      result.push(
        new Paragraph({
          children: [
            new TextRun({
              text:
                String(
                  block.language
                ).toUpperCase(),

              bold:
                true,

              font:
                "Aptos",

              size:
                15,

              color:
                palette.muted
            })
          ],

          shading: {
            fill:
              palette.code
          },

          border: {
            top: {
              color:
                palette.border,

              style:
                BorderStyle.SINGLE,

              size:
                6
            },

            left: {
              color:
                palette.border,

              style:
                BorderStyle.SINGLE,

              size:
                6
            },

            right: {
              color:
                palette.border,

              style:
                BorderStyle.SINGLE,

              size:
                6
            }
          },

          indent: {
            left:
              180,

            right:
              180
          },

          spacing: {
            before:
              160,

            after:
              0
          },

          keepNext:
            true
        })
      );
    }


    const sourceLines =
      String(
        block.text ||
        ""
      ).split(
        "\n"
      );


    sourceLines.forEach(
      (
        line,
        index
      ) => {

        const last =
          index ===
          sourceLines.length -
          1;


        result.push(
          new Paragraph({
            children: [
              new TextRun({
                text:
                  line,

                font:
                  "Courier New",

                size:
                  18,

                color:
                  palette.ink
              })
            ],

            shading: {
              fill:
                palette.code
            },

            border: {
              left: {
                color:
                  palette.border,

                style:
                  BorderStyle.SINGLE,

                size:
                  6
              },

              right: {
                color:
                  palette.border,

                style:
                  BorderStyle.SINGLE,

                size:
                  6
              },

              bottom:
                last
                  ? {
                      color:
                        palette.border,

                      style:
                        BorderStyle.SINGLE,

                      size:
                        6
                    }
                  : undefined
            },

            indent: {
              left:
                180,

              right:
                180
            },

            spacing: {
              before:
                0,

              after:
                last
                  ? 180
                  : 0,

              line:
                260
            },

            keepLines:
              true
          })
        );

      }
    );


    return result;
  }


  const children = [];


  for (
    const block
    of composerBlocks(
      title,
      content
    )
  ) {
    if (
      block.kind ===
      "title"
    ) {
      children.push(
        new Paragraph({
          children: [
            new TextRun({
              text:
                archetypeLabel.toUpperCase(),

              bold:
                true,

              font:
                "Aptos",

              size:
                17,

              color:
                palette.accent
            })
          ],

          spacing: {
            before:
              0,

            after:
              80
          },

          keepNext:
            true
        })
      );


      children.push(
        new Paragraph({
          children:
            runs(
              block.text,
              {
                bold:
                  true,

                size:
                  48,

                color:
                  palette.accentDark
              }
            ),

          spacing: {
            before:
              0,

            after:
              150
          },

          border: {
            bottom: {
              color:
                palette.accent,

              style:
                BorderStyle.SINGLE,

              size:
                18,

              space:
                10
            }
          },

          keepNext:
            true,

          keepLines:
            true
        })
      );


      const subtitle =
        audience !==
          "general"
          ? `${archetypeLabel} · ${audienceLabel} audience`
          : `${archetypeLabel} · Generated by Vector`;


      children.push(
        new Paragraph({
          children: [
            new TextRun({
              text:
                subtitle,

              font:
                "Aptos",

              size:
                18,

              color:
                palette.muted
            })
          ],

          spacing: {
            after:
              300
          }
        })
      );


      continue;
    }


    if (
      block.kind ===
      "blank"
    ) {
      children.push(
        new Paragraph({
          children: [
            new TextRun({
              text:
                ""
            })
          ],

          spacing: {
            after:
              50
          }
        })
      );


      continue;
    }


    if (
      block.kind ===
      "divider"
    ) {
      children.push(
        new Paragraph({
          border: {
            bottom: {
              color:
                palette.border,

              style:
                BorderStyle.SINGLE,

              size:
                8,

              space:
                8
            }
          },

          spacing: {
            before:
              140,

            after:
              220
          }
        })
      );


      continue;
    }


    if (
      block.kind ===
      "callout"
    ) {
      children.push(
        new Paragraph({
          children:
            runs(
              block.text,
              {
                size:
                  21,

                color:
                  "21433C"
              }
            ),

          shading: {
            fill:
              palette.soft
          },

          border: {
            left: {
              color:
                palette.accent,

              style:
                BorderStyle.SINGLE,

              size:
                22,

              space:
                10
            }
          },

          indent: {
            left:
              280,

            right:
              180
          },

          spacing: {
            before:
              140,

            after:
              220,

            line:
              300
          },

          keepLines:
            true,

          widowControl:
            true
        })
      );


      continue;
    }


    if (
      /^h[1-4]$/.test(
        block.kind
      )
    ) {
      const style =
        headingStyle(
          block.kind
        );


      children.push(
        new Paragraph({
          heading:
            style.heading,

          children:
            runs(
              block.text,
              {
                bold:
                  true,

                size:
                  style.size,

                color:
                  style.color
              }
            ),

          spacing: {
            before:
              style.before,

            after:
              style.after
          },

          keepNext:
            true,

          keepLines:
            true,

          widowControl:
            true
        })
      );


      continue;
    }


    if (
      block.kind ===
      "table"
    ) {
      children.push(
        renderTable(
          block
        )
      );


      children.push(
        new Paragraph({
          children: [
            new TextRun({
              text:
                ""
            })
          ],

          spacing: {
            after:
              120
          }
        })
      );


      continue;
    }


    if (
      block.kind ===
      "codeblock"
    ) {
      children.push(
        ...renderCodeBlock(
          block
        )
      );


      continue;
    }


    if (
      block.kind ===
      "bullet"
    ) {
      children.push(
        new Paragraph({
          children:
            runs(
              block.text,
              {
                size:
                  22
              }
            ),

          bullet: {
            level:
              0
          },

          spacing: {
            after:
              100,

            line:
              300
          },

          keepLines:
            true,

          widowControl:
            true
        })
      );


      continue;
    }


    if (
      block.kind ===
      "number"
    ) {
      children.push(
        new Paragraph({
          children:
            runs(
              block.text,
              {
                size:
                  22
              }
            ),

          numbering: {
            reference:
              "vector-numbering",

            level:
              0
          },

          spacing: {
            after:
              100,

            line:
              300
          },

          keepLines:
            true,

          widowControl:
            true
        })
      );


      continue;
    }


    children.push(
      new Paragraph({
        children:
          runs(
            block.text,
            {
              size:
                22
            }
          ),

        spacing: {
          after:
            150,

          line:
            310
        },

        widowControl:
          true
      })
    );
  }


  /*
   * VECTOR_DOCX_RUNNING_HEADER_577
   */
  const runningHeader =
    new Header({
      children: [
        new Paragraph({
          alignment:
            AlignmentType.RIGHT,

          children: [
            new TextRun({
              text:
                documentTitle,

              bold:
                true,

              font:
                "Aptos",

              size:
                16,

              color:
                palette.accentDark
            }),

            new TextRun({
              text:
                `  ·  ${archetypeLabel}`,

              font:
                "Aptos",

              size:
                15,

              color:
                palette.muted
            })
          ],

          border: {
            bottom: {
              color:
                palette.border,

              style:
                BorderStyle.SINGLE,

              size:
                6,

              space:
                8
            }
          }
        })
      ]
    });


  /*
   * VECTOR_DOCX_PAGE_NUMBERS_577
   */
  const footer =
    new Footer({
      children: [
        new Paragraph({
          alignment:
            AlignmentType.RIGHT,

          children: [
            new TextRun({
              text:
                "Generated by Vector  ·  Page ",

              font:
                "Aptos",

              size:
                17,

              color:
                palette.muted
            }),

            new TextRun({
              children: [
                PageNumber.CURRENT
              ],

              font:
                "Aptos",

              size:
                17,

              color:
                palette.muted
            }),

            new TextRun({
              text:
                " of ",

              font:
                "Aptos",

              size:
                17,

              color:
                palette.muted
            }),

            new TextRun({
              children: [
                PageNumber.TOTAL_PAGES
              ],

              font:
                "Aptos",

              size:
                17,

              color:
                palette.muted
            })
          ]
        })
      ]
    });


  const document =
    new Document({
      creator:
        "Vector",

      lastModifiedBy:
        "Vector",

      title:
        documentTitle,

      subject:
        audience !==
          "general"
          ? `${archetypeLabel} for ${audienceLabel} audience`
          : archetypeLabel,

      description:
        `Generated by Vector · ${archetypeLabel}`,

      keywords:
        `Vector, ${archetype}, ${audience}`,

      numbering: {
        config: [
          {
            reference:
              "vector-numbering",

            levels: [
              {
                level:
                  0,

                format:
                  "decimal",

                text:
                  "%1.",

                alignment:
                  "start"
              }
            ]
          }
        ]
      },

      sections: [
        {
          properties: {
            page: {
              margin: {
                top:
                  1050,

                right:
                  900,

                bottom:
                  900,

                left:
                  900,

                header:
                  420,

                footer:
                  420
              }
            }
          },

          headers: {
            default:
              runningHeader
          },

          footers: {
            default:
              footer
          },

          children:
            children.length >
            0
              ? children
              : [
                  new Paragraph(
                    "Vector document"
                  )
                ]
        }
      ]
    });


  return Buffer.from(
    await Packer.toBuffer(
      document
    )
  );
}


function safePdfText(value) {
  return String(
    value ||
    ""
  )
    .replace(
      /[\u2018\u2019]/g,
      "'"
    )
    .replace(
      /[\u201C\u201D]/g,
      '"'
    )
    .replace(
      /[\u2013\u2014]/g,
      "-"
    )
    .replace(
      /\u2026/g,
      "..."
    )
    .replace(
      /[^\x20-\x7E\u00A0-\u00FF]/g,
      "?"
    );
}


function wrapPdfLine(
  text,
  font,
  size,
  maxWidth
) {
  const words =
    safePdfText(
      text
    )
      .split(
        /\s+/
      )
      .filter(
        Boolean
      );

  if (
    words.length ===
    0
  ) {
    return [
      ""
    ];
  }

  const lines = [];
  let current =
    words[0];

  for (
    let index = 1;
    index <
      words.length;
    index += 1
  ) {
    const candidate =
      `${current} ${words[index]}`;

    if (
      font.widthOfTextAtSize(
        candidate,
        size
      ) <=
      maxWidth
    ) {
      current =
        candidate;

      continue;
    }

    lines.push(
      current
    );

    current =
      words[index];
  }

  lines.push(
    current
  );

  return lines;
}


/*
 * VECTOR_PDF_COMPOSER_V3_576
 *
 * Semantic, provider-independent PDF renderer.
 *
 * Features:
 *   - Artifact Intelligence plan
 *   - report-aware title area
 *   - running headers
 *   - headings
 *   - callouts
 *   - lists
 *   - Markdown tables
 *   - fenced code blocks
 *   - multi-page tables/code
 *   - Page X of Y footer
 */
async function createPdf({
  title,
  content,
  artifactPlan = null
}) {
  const {
    PDFDocument,
    StandardFonts,
    rgb
  } =
    await import(
      "pdf-lib"
    );


  const pdf =
    await PDFDocument.create();


  const fonts = {
    regular:
      await pdf.embedFont(
        StandardFonts.Helvetica
      ),

    bold:
      await pdf.embedFont(
        StandardFonts.HelveticaBold
      ),

    italic:
      await pdf.embedFont(
        StandardFonts.HelveticaOblique
      ),

    mono:
      await pdf.embedFont(
        StandardFonts.Courier
      )
  };


  const PAGE_WIDTH =
    595.28;

  const PAGE_HEIGHT =
    841.89;

  const LEFT =
    54;

  const RIGHT =
    54;

  const CONTENT_WIDTH =
    PAGE_WIDTH -
    LEFT -
    RIGHT;

  const FOOTER_Y =
    30;


  const palette = {
    ink:
      rgb(
        0.10,
        0.15,
        0.17
      ),

    muted:
      rgb(
        0.39,
        0.46,
        0.48
      ),

    accent:
      rgb(
        0.16,
        0.59,
        0.47
      ),

    accentDark:
      rgb(
        0.07,
        0.24,
        0.27
      ),

    accentSoft:
      rgb(
        0.91,
        0.97,
        0.95
      ),

    line:
      rgb(
        0.87,
        0.90,
        0.91
      ),

    white:
      rgb(
        1,
        1,
        1
      ),

    code:
      rgb(
        0.95,
        0.96,
        0.96
      ),

    tableAlt:
      rgb(
        0.97,
        0.985,
        0.98
      ),

    tableHeader:
      rgb(
        0.07,
        0.24,
        0.27
      )
  };


  function displayLabel(
    value
  ) {
    return String(
      value ||
      ""
    )
      .replace(
        /_/g,
        " "
      )
      .replace(
        /\b\w/g,
        (
          char
        ) =>
          char.toUpperCase()
      )
      .trim();
  }


  const archetype =
    String(
      artifactPlan
        ?.archetype ||
      "report"
    );


  const audience =
    String(
      artifactPlan
        ?.audience ||
      "general"
    );


  const archetypeLabel =
    displayLabel(
      archetype
    ) ||
    "Report";


  const audienceLabel =
    displayLabel(
      audience
    );


  const safeTitle =
    safePdfText(
      title ||
      "Vector document"
    );


  pdf.setTitle(
    safeTitle
  );

  pdf.setAuthor(
    "Vector"
  );

  pdf.setCreator(
    "Vector"
  );

  pdf.setProducer(
    "Vector"
  );

  pdf.setSubject(
    safePdfText(
      audience !==
        "general"
        ? `${archetypeLabel} for ${audienceLabel} audience`
        : archetypeLabel
    )
  );

  pdf.setKeywords([
    "Vector",
    archetype,
    audience
  ]);


  function fontFor(
    run
  ) {
    if (
      run.code
    ) {
      return fonts.mono;
    }


    if (
      run.bold
    ) {
      return fonts.bold;
    }


    if (
      run.italic
    ) {
      return fonts.italic;
    }


    return fonts.regular;
  }


  function fitText(
    value,
    font,
    size,
    maxWidth
  ) {
    let text =
      safePdfText(
        value
      );


    if (
      font.widthOfTextAtSize(
        text,
        size
      ) <=
      maxWidth
    ) {
      return text;
    }


    while (
      text.length >
        3 &&
      font.widthOfTextAtSize(
        `${text}...`,
        size
      ) >
        maxWidth
    ) {
      text =
        text.slice(
          0,
          -1
        );
    }


    return `${text.trimEnd()}...`;
  }


  function wrappedRuns(
    value,
    size,
    maxWidth
  ) {
    const sourceRuns =
      composerInlineRuns(
        value
      );


    const lines = [];

    let current = [];
    let width = 0;


    for (
      const run
      of sourceRuns
    ) {
      const words =
        String(
          run.text ||
          ""
        )
          .split(
            /\s+/
          )
          .filter(
            Boolean
          );


      for (
        const word
        of words
      ) {
        const font =
          fontFor(
            run
          );


        const safeWord =
          safePdfText(
            word
          );


        const prefix =
          current.length >
            0
            ? " "
            : "";


        const token =
          prefix +
          safeWord;


        const tokenWidth =
          font.widthOfTextAtSize(
            token,
            size
          );


        if (
          current.length >
            0 &&
          width +
            tokenWidth >
            maxWidth
        ) {
          lines.push(
            current
          );


          current = [
            {
              ...run,

              text:
                safeWord
            }
          ];


          width =
            font.widthOfTextAtSize(
              safeWord,
              size
            );

        } else {
          current.push({
            ...run,

            text:
              token
          });


          width +=
            tokenWidth;
        }
      }
    }


    if (
      current.length >
      0
    ) {
      lines.push(
        current
      );
    }


    return (
      lines.length >
        0
        ? lines
        : [
            [
              {
                text:
                  "",

                bold:
                  false,

                italic:
                  false,

                code:
                  false
              }
            ]
          ]
    );
  }


  function wrappedPlain(
    value,
    font,
    size,
    maxWidth
  ) {
    const source =
      safePdfText(
        value
      );


    if (
      !source
    ) {
      return [
        ""
      ];
    }


    const words =
      source.split(
        /\s+/
      );


    const result = [];

    let current =
      "";


    for (
      const word
      of words
    ) {
      const candidate =
        current
          ? `${current} ${word}`
          : word;


      if (
        !current ||
        font.widthOfTextAtSize(
          candidate,
          size
        ) <=
          maxWidth
      ) {
        current =
          candidate;

        continue;
      }


      result.push(
        current
      );


      if (
        font.widthOfTextAtSize(
          word,
          size
        ) <=
        maxWidth
      ) {
        current =
          word;

        continue;
      }


      let piece =
        "";


      for (
        const char
        of word
      ) {
        const next =
          piece +
          char;


        if (
          piece &&
          font.widthOfTextAtSize(
            next,
            size
          ) >
            maxWidth
        ) {
          result.push(
            piece
          );

          piece =
            char;

        } else {
          piece =
            next;
        }
      }


      current =
        piece;
    }


    if (
      current
    ) {
      result.push(
        current
      );
    }


    return (
      result.length >
        0
        ? result
        : [
            ""
          ]
    );
  }


  function drawRunLine(
    page,
    runs,
    x,
    y,
    size,
    color
  ) {
    let cursor =
      x;


    for (
      const run
      of runs
    ) {
      const font =
        fontFor(
          run
        );


      const value =
        safePdfText(
          run.text
      );


      page.drawText(
        value,
        {
          x:
            cursor,

          y,

          size,

          font,

          color
        }
      );


      cursor +=
        font.widthOfTextAtSize(
          value,
          size
        );
    }
  }


  let currentSection =
    archetypeLabel;


  function newPage(
    first = false
  ) {
    const page =
      pdf.addPage([
        PAGE_WIDTH,
        PAGE_HEIGHT
      ]);


    if (
      first
    ) {
      page.drawRectangle({
        x:
          0,

        y:
          PAGE_HEIGHT -
          184,

        width:
          PAGE_WIDTH,

        height:
          184,

        color:
          palette.accentDark
      });


      page.drawRectangle({
        x:
          LEFT,

        y:
          PAGE_HEIGHT -
          52,

        width:
          54,

        height:
          4,

        color:
          palette.accent
      });


      page.drawText(
        safePdfText(
          archetypeLabel.toUpperCase()
        ),
        {
          x:
            LEFT,

          y:
            PAGE_HEIGHT -
            78,

          size:
            8.6,

          font:
            fonts.bold,

          color:
            palette.accent
        }
      );


      const titleLines =
        wrappedRuns(
          title ||
          "Vector document",
          27,
          CONTENT_WIDTH
        ).slice(
          0,
          3
        );


      let titleY =
        PAGE_HEIGHT -
        109;


      for (
        const line
        of titleLines
      ) {
        drawRunLine(
          page,
          line.map(
            (
              run
            ) => ({
              ...run,

              bold:
                true
            })
          ),
          LEFT,
          titleY,
          27,
          palette.white
        );


        titleY -=
          32;
      }


      const subtitle =
        audience !==
          "general"
          ? `${archetypeLabel} · ${audienceLabel} audience`
          : archetypeLabel;


      page.drawText(
        fitText(
          subtitle,
          fonts.regular,
          9.2,
          CONTENT_WIDTH
        ),
        {
          x:
            LEFT,

          y:
            PAGE_HEIGHT -
            163,

          size:
            9.2,

          font:
            fonts.regular,

          color:
            rgb(
              0.72,
              0.83,
              0.82
            )
        }
      );


      return {
        page,

        y:
          PAGE_HEIGHT -
          222
      };
    }


    /*
     * VECTOR_PDF_RUNNING_HEADER_576
     */
    const headerTitle =
      fitText(
        title ||
        "Vector document",
        fonts.bold,
        8.4,
        CONTENT_WIDTH *
        0.58
      );


    page.drawText(
      headerTitle,
      {
        x:
          LEFT,

        y:
          PAGE_HEIGHT -
          34,

        size:
          8.4,

        font:
          fonts.bold,

        color:
          palette.accentDark
      }
    );


    const sectionLabel =
      fitText(
        currentSection ||
        archetypeLabel,
        fonts.regular,
        7.8,
        CONTENT_WIDTH *
        0.34
      );


    const sectionWidth =
      fonts.regular
        .widthOfTextAtSize(
          sectionLabel,
          7.8
        );


    page.drawText(
      sectionLabel,
      {
        x:
          PAGE_WIDTH -
          RIGHT -
          sectionWidth,

        y:
          PAGE_HEIGHT -
          34,

        size:
          7.8,

        font:
          fonts.regular,

        color:
          palette.muted
      }
    );


    page.drawLine({
      start: {
        x:
          LEFT,

        y:
          PAGE_HEIGHT -
          47
      },

      end: {
        x:
          PAGE_WIDTH -
          RIGHT,

        y:
          PAGE_HEIGHT -
          47
      },

      thickness:
        0.6,

      color:
        palette.line
    });


    return {
      page,

      y:
        PAGE_HEIGHT -
        70
    };
  }


  let state =
    newPage(
      true
    );


  function ensureSpace(
    amount
  ) {
    if (
      state.y -
      amount <
      62
    ) {
      state =
        newPage(
          false
        );
    }
  }


  function codeVisualLines(
    value,
    size,
    maxWidth
  ) {
    const charWidth =
      fonts.mono
        .widthOfTextAtSize(
          "M",
          size
        );


    const maxChars =
      Math.max(
        12,
        Math.floor(
          maxWidth /
          charWidth
        )
      );


    const output = [];


    for (
      const sourceLine
      of String(
        value ||
        ""
      ).split(
        "\n"
      )
    ) {
      const safe =
        safePdfText(
          sourceLine
        );


      if (
        safe.length ===
        0
      ) {
        output.push(
          ""
        );

        continue;
      }


      let cursor =
        0;


      while (
        cursor <
        safe.length
      ) {
        output.push(
          safe.slice(
            cursor,
            cursor +
            maxChars
          )
        );

        cursor +=
          maxChars;
      }
    }


    return (
      output.length
        ? output
        : [
            ""
          ]
    );
  }


  function renderCodeBlock(
    block
  ) {
    const size =
      8.5;

    const lineHeight =
      12.8;

    const paddingX =
      14;

    const paddingTop =
      block.language
        ? 28
        : 16;

    const paddingBottom =
      13;


    const lines =
      codeVisualLines(
        block.text,
        size,
        CONTENT_WIDTH -
        paddingX *
        2
      );


    let offset =
      0;


    while (
      offset <
      lines.length
    ) {
      const availableHeight =
        state.y -
        70;


      const availableLines =
        Math.floor(
          (
            availableHeight -
            paddingTop -
            paddingBottom
          ) /
          lineHeight
        );


      if (
        availableLines <
        1
      ) {
        state =
          newPage(
            false
          );

        continue;
      }


      const take =
        Math.min(
          availableLines,
          lines.length -
          offset
        );


      const chunk =
        lines.slice(
          offset,
          offset +
          take
        );


      const boxHeight =
        paddingTop +
        paddingBottom +
        chunk.length *
        lineHeight;


      state.page.drawRectangle({
        x:
          LEFT,

        y:
          state.y -
          boxHeight,

        width:
          CONTENT_WIDTH,

        height:
          boxHeight,

        color:
          palette.code,

        borderColor:
          palette.line,

        borderWidth:
          0.6
      });


      if (
        block.language
      ) {
        state.page.drawText(
          safePdfText(
            block.language
              .toUpperCase()
          ),
          {
            x:
              LEFT +
              paddingX,

            y:
              state.y -
              16,

            size:
              7.2,

            font:
              fonts.bold,

            color:
              palette.muted
          }
        );
      }


      let y =
        state.y -
        paddingTop;


      for (
        const line
        of chunk
      ) {
        state.page.drawText(
          line,
          {
            x:
              LEFT +
              paddingX,

            y,

            size,

            font:
              fonts.mono,

            color:
              palette.ink
          }
        );


        y -=
          lineHeight;
      }


      state.y -=
        boxHeight +
        14;


      offset +=
        take;


      if (
        offset <
        lines.length
      ) {
        state =
          newPage(
            false
          );
      }
    }
  }


  function renderTable(
    block
  ) {
    const headers =
      Array.isArray(
        block.headers
      )
        ? block.headers
        : [];


    const rows =
      Array.isArray(
        block.rows
      )
        ? block.rows
        : [];


    const columnCount =
      Math.max(
        1,
        headers.length,
        ...rows.map(
          (
            row
          ) =>
            Array.isArray(
              row
            )
              ? row.length
              : 1
        )
      );


    const fontSize =
      columnCount <=
        3
        ? 8.8
        : columnCount <=
            5
          ? 8.0
          : columnCount <=
              7
            ? 7.1
            : 6.3;


    const lineHeight =
      fontSize +
      3.2;


    const widths =
      Array(
        columnCount
      ).fill(
        CONTENT_WIDTH /
        columnCount
      );


    function preparedRow(
      cells,
      header = false
    ) {
      const font =
        header
          ? fonts.bold
          : fonts.regular;


      const values =
        Array.from(
          {
            length:
              columnCount
          },
          (
            _,
            index
          ) =>
            cells?.[
              index
            ] ??
            ""
        );


      const cellLines =
        values.map(
          (
            value,
            index
          ) =>
            wrappedPlain(
              composerPlainText(
                String(
                  value ??
                  ""
                )
              ),
              font,
              fontSize,
              widths[
                index
              ] -
              12
            )
        );


      return {
        cellLines,

        maxLines:
          Math.max(
            1,
            ...cellLines.map(
              (
                lines
              ) =>
                lines.length
            )
          )
      };
    }


    function drawSegment({
      cellLines,
      startLine,
      lineCount,
      header = false,
      zebra = false
    }) {
      const rowHeight =
        Math.max(
          24,
          lineCount *
          lineHeight +
          10
        );


      const background =
        header
          ? palette.tableHeader
          : zebra
            ? palette.tableAlt
            : palette.white;


      state.page.drawRectangle({
        x:
          LEFT,

        y:
          state.y -
          rowHeight,

        width:
          CONTENT_WIDTH,

        height:
          rowHeight,

        color:
          background,

        borderColor:
          palette.line,

        borderWidth:
          0.55
      });


      let x =
        LEFT;


      for (
        let column = 0;
        column <
          columnCount;
        column += 1
      ) {
        if (
          column >
          0
        ) {
          state.page.drawLine({
            start: {
              x,

              y:
                state.y
            },

            end: {
              x,

              y:
                state.y -
                rowHeight
            },

            thickness:
              0.45,

            color:
              palette.line
          });
        }


        const lines =
          cellLines[
            column
          ] ||
          [
            ""
          ];


        let y =
          state.y -
          8 -
          fontSize;


        for (
          let lineIndex = 0;
          lineIndex <
            lineCount;
          lineIndex += 1
        ) {
          const value =
            lines[
              startLine +
              lineIndex
            ];


          if (
            value !==
            undefined
          ) {
            state.page.drawText(
              value,
              {
                x:
                  x +
                  6,

                y,

                size:
                  fontSize,

                font:
                  header
                    ? fonts.bold
                    : fonts.regular,

                color:
                  header
                    ? palette.white
                    : palette.ink
              }
            );
          }


          y -=
            lineHeight;
        }


        x +=
          widths[
            column
          ];
      }


      state.y -=
        rowHeight;
    }


    const preparedHeader =
      preparedRow(
        headers,
        true
      );


    function drawHeader() {
      const required =
        Math.max(
          24,
          preparedHeader.maxLines *
          lineHeight +
          10
        );


      if (
        state.y -
        required <
        62
      ) {
        state =
          newPage(
            false
          );
      }


      drawSegment({
        cellLines:
          preparedHeader.cellLines,

        startLine:
          0,

        lineCount:
          preparedHeader.maxLines,

        header:
          true
      });
    }


    ensureSpace(
      70
    );


    drawHeader();


    for (
      let rowIndex = 0;
      rowIndex <
        rows.length;
      rowIndex += 1
    ) {
      const prepared =
        preparedRow(
          rows[
            rowIndex
          ],
          false
        );


      let offset =
        0;


      while (
        offset <
        prepared.maxLines
      ) {
        const availableLines =
          Math.floor(
            (
              state.y -
              72
            ) /
            lineHeight
          );


        if (
          availableLines <
          1
        ) {
          state =
            newPage(
              false
            );

          drawHeader();

          continue;
        }


        const take =
          Math.min(
            availableLines,
            prepared.maxLines -
            offset
          );


        const required =
          Math.max(
            24,
            take *
            lineHeight +
            10
          );


        if (
          state.y -
          required <
          62
        ) {
          state =
            newPage(
              false
            );

          drawHeader();

          continue;
        }


        drawSegment({
          cellLines:
            prepared.cellLines,

          startLine:
            offset,

          lineCount:
            take,

          zebra:
            rowIndex %
              2 ===
            1
        });


        offset +=
          take;


        if (
          offset <
          prepared.maxLines
        ) {
          state =
            newPage(
              false
            );

          drawHeader();
        }
      }
    }


    state.y -=
      15;
  }


  const blocks =
    composerBlocks(
      title,
      content
    );


  let numberCounter =
    0;


  for (
    const block
    of blocks
  ) {
    if (
      block.kind ===
      "title"
    ) {
      continue;
    }


    if (
      block.kind ===
      "blank"
    ) {
      state.y -=
        8;

      continue;
    }


    if (
      block.kind ===
      "divider"
    ) {
      ensureSpace(
        28
      );


      state.page.drawLine({
        start: {
          x:
            LEFT,

          y:
            state.y -
            2
        },

        end: {
          x:
            PAGE_WIDTH -
            RIGHT,

          y:
            state.y -
            2
        },

        thickness:
          0.8,

        color:
          palette.line
      });


      state.y -=
        24;

      continue;
    }


    if (
      block.kind ===
      "callout"
    ) {
      const size =
        10.5;

      const lineHeight =
        15.5;


      const lines =
        wrappedRuns(
          block.text,
          size,
          CONTENT_WIDTH -
          34
        );


      const height =
        Math.max(
          52,
          lines.length *
          lineHeight +
          26
        );


      ensureSpace(
        height +
        18
      );


      state.page.drawRectangle({
        x:
          LEFT,

        y:
          state.y -
          height,

        width:
          CONTENT_WIDTH,

        height,

        color:
          palette.accentSoft
      });


      state.page.drawRectangle({
        x:
          LEFT,

        y:
          state.y -
          height,

        width:
          4,

        height,

        color:
          palette.accent
      });


      let y =
        state.y -
        20;


      for (
        const line
        of lines
      ) {
        drawRunLine(
          state.page,
          line,
          LEFT +
          20,
          y,
          size,
          palette.accentDark
        );


        y -=
          lineHeight;
      }


      state.y -=
        height +
        18;

      continue;
    }


    if (
      /^h[1-4]$/.test(
        block.kind
      )
    ) {
      const styles = {
        h1: {
          size:
            20,

          line:
            25,

          before:
            18,

          after:
            12,

          color:
            palette.accentDark
        },

        h2: {
          size:
            15,

          line:
            20,

          before:
            16,

          after:
            9,

          color:
            palette.accentDark
        },

        h3: {
          size:
            12.5,

          line:
            17,

          before:
            12,

          after:
            7,

          color:
            palette.ink
        },

        h4: {
          size:
            11,

          line:
            15,

          before:
            10,

          after:
            6,

          color:
            palette.muted
        }
      };


      const style =
        styles[
          block.kind
        ];


      const lines =
        wrappedRuns(
          block.text,
          style.size,
          CONTENT_WIDTH
        );


      ensureSpace(
        style.before +
        lines.length *
        style.line +
        style.after +
        10
      );


      if (
        block.kind ===
          "h1" ||
        block.kind ===
          "h2"
      ) {
        currentSection =
          composerPlainText(
            block.text
          );
      }


      state.y -=
        style.before;


      for (
        const line
        of lines
      ) {
        drawRunLine(
          state.page,
          line.map(
            (
              run
            ) => ({
              ...run,

              bold:
                true
            })
          ),
          LEFT,
          state.y,
          style.size,
          style.color
        );


        state.y -=
          style.line;
      }


      if (
        block.kind ===
        "h1"
      ) {
        state.page.drawRectangle({
          x:
            LEFT,

          y:
            state.y +
            3,

          width:
            30,

          height:
            2.5,

          color:
            palette.accent
        });
      }


      state.y -=
        style.after;


      numberCounter =
        0;

      continue;
    }


    if (
      block.kind ===
      "table"
    ) {
      renderTable(
        block
      );

      numberCounter =
        0;

      continue;
    }


    if (
      block.kind ===
      "codeblock"
    ) {
      renderCodeBlock(
        block
      );

      numberCounter =
        0;

      continue;
    }


    if (
      block.kind ===
      "bullet"
    ) {
      const size =
        10.7;

      const lineHeight =
        16;


      const lines =
        wrappedRuns(
          block.text,
          size,
          CONTENT_WIDTH -
          28
        );


      ensureSpace(
        lines.length *
        lineHeight +
        9
      );


      state.page.drawCircle({
        x:
          LEFT +
          5,

        y:
          state.y +
          4,

        size:
          2.5,

        color:
          palette.accent
      });


      for (
        const line
        of lines
      ) {
        drawRunLine(
          state.page,
          line,
          LEFT +
          20,
          state.y,
          size,
          palette.ink
        );


        state.y -=
          lineHeight;
      }


      state.y -=
        5;

      continue;
    }


    if (
      block.kind ===
      "number"
    ) {
      numberCounter +=
        1;


      const label =
        `${
          block.number ||
          numberCounter
        }.`;


      const size =
        10.7;

      const lineHeight =
        16;


      const lines =
        wrappedRuns(
          block.text,
          size,
          CONTENT_WIDTH -
          34
        );


      ensureSpace(
        lines.length *
        lineHeight +
        9
      );


      state.page.drawText(
        safePdfText(
          label
        ),
        {
          x:
            LEFT,

          y:
            state.y,

          size:
            10.2,

          font:
            fonts.bold,

          color:
            palette.accent
        }
      );


      for (
        const line
        of lines
      ) {
        drawRunLine(
          state.page,
          line,
          LEFT +
          28,
          state.y,
          size,
          palette.ink
        );


        state.y -=
          lineHeight;
      }


      state.y -=
        5;

      continue;
    }


    numberCounter =
      0;


    const size =
      10.7;

    const lineHeight =
      16;


    const lines =
      wrappedRuns(
        block.text,
        size,
        CONTENT_WIDTH
      );


    ensureSpace(
      lines.length *
      lineHeight +
      10
    );


    for (
      const line
      of lines
    ) {
      drawRunLine(
        state.page,
        line,
        LEFT,
        state.y,
        size,
        palette.ink
      );


      state.y -=
        lineHeight;
    }


    state.y -=
      9;
  }


  /*
   * VECTOR_PDF_PAGE_NUMBERS_576
   *
   * Footer is added after final page count is known.
   */
  const pages =
    pdf.getPages();


  for (
    let index = 0;
    index <
    pages.length;
    index += 1
  ) {
    const page =
      pages[
        index
      ];


    page.drawLine({
      start: {
        x:
          LEFT,

        y:
          45
      },

      end: {
        x:
          PAGE_WIDTH -
          RIGHT,

        y:
          45
      },

      thickness:
        0.5,

      color:
        palette.line
    });


    page.drawText(
      "Generated by Vector",
      {
        x:
          LEFT,

        y:
          FOOTER_Y,

        size:
          7.8,

        font:
          fonts.regular,

        color:
          palette.muted
      }
    );


    const pageLabel =
      `Page ${
        index + 1
      } of ${
        pages.length
      }`;


    const pageLabelWidth =
      fonts.regular
        .widthOfTextAtSize(
          pageLabel,
          7.8
        );


    page.drawText(
      pageLabel,
      {
        x:
          PAGE_WIDTH -
          RIGHT -
          pageLabelWidth,

        y:
          FOOTER_Y,

        size:
          7.8,

        font:
          fonts.regular,

        color:
          palette.muted
      }
    );
  }


  return Buffer.from(
    await pdf.save()
  );
}


async function createXlsx({
  title,
  content,
  sheets
}) {
  /*
   * VECTOR_XLSX_COMPOSER_V2_57443
   *
   * Professional structured workbook renderer.
   */

  const imported =
    await import(
      "exceljs"
    );

  const ExcelJS =
    imported.default ||
    imported;

  const workbook =
    new ExcelJS.Workbook();


  workbook.creator =
    "Vector";

  workbook.lastModifiedBy =
    "Vector";

  workbook.title =
    String(
      title ||
      "Vector workbook"
    );

  workbook.subject =
    "Generated by Vector";


  const palette = {
    dark:
      "FF123A42",

    accent:
      "FF37A786",

    header:
      "FF174F58",

    headerText:
      "FFFFFFFF",

    body:
      "FF263338",

    muted:
      "FF748187",

    border:
      "FFDDE5E7",

    alternate:
      "FFF6F9F8",

    white:
      "FFFFFFFF"
  };


  function safeSheetName(
    value,
    fallback
  ) {
    let name =
      String(
        value ||
        fallback ||
        "Sheet"
      )
        .replace(
          /[\\/*?:[\]]/g,
          "-"
        )
        .trim();

    if (!name) {
      name =
        fallback ||
        "Sheet";
    }

    return name.slice(
      0,
      31
    );
  }


  function uniqueSheetName(
    value,
    used
  ) {
    const base =
      safeSheetName(
        value,
        "Sheet"
      );

    let candidate =
      base;

    let index =
      2;

    while (
      used.has(
        candidate.toLowerCase()
      )
    ) {
      const suffix =
        ` ${index}`;

      candidate =
        base
          .slice(
            0,
            Math.max(
              1,
              31 -
              suffix.length
            )
          ) +
        suffix;

      index +=
        1;
    }

    used.add(
      candidate.toLowerCase()
    );

    return candidate;
  }


  function fallbackRows() {
    const value =
      String(
        content ||
        ""
      ).trim();

    if (!value) {
      return [
        [
          "Information"
        ],
        [
          "No structured data was provided."
        ]
      ];
    }

    return [
      [
        "Content"
      ],

      ...value
        .split(
          /\r?\n/
        )
        .map(
          (line) =>
            line.trim()
        )
        .filter(
          Boolean
        )
        .map(
          (line) => [
            line
          ]
        )
    ];
  }


  const sourceSheets =
    Array.isArray(
      sheets
    ) &&
    sheets.length >
      0
      ? sheets
      : [
          {
            name:
              "Overview",

            rows:
              fallbackRows()
          }
        ];


  const usedNames =
    new Set();


  for (
    let sheetIndex = 0;
    sheetIndex <
      sourceSheets.length;
    sheetIndex += 1
  ) {
    const source =
      sourceSheets[
        sheetIndex
      ] ||
      {};


    const sheetName =
      uniqueSheetName(
        source.name ||
        `Sheet ${
          sheetIndex + 1
        }`,
        usedNames
      );


    const rows =
      Array.isArray(
        source.rows
      ) &&
      source.rows.length >
        0
        ? source.rows
        : [
            [
              "Information"
            ],
            [
              "No data"
            ]
          ];


    let maxColumns =
      1;


    for (
      const row
      of rows
    ) {
      maxColumns =
        Math.max(
          maxColumns,
          Array.isArray(
            row
          )
            ? row.length
            : 1
        );
    }


    const worksheet =
      workbook.addWorksheet(
        sheetName
      );


    /*
     * Workbook / sheet title
     */
    worksheet.mergeCells(
      1,
      1,
      1,
      maxColumns
    );


    const titleCell =
      worksheet.getCell(
        1,
        1
      );


    titleCell.value =
      (
        title &&
        sourceSheets.length >
          1
      )
        ? `${title} · ${sheetName}`
        : (
            title ||
            sheetName
          );


    titleCell.font = {
      name:
        "Aptos Display",

      size:
        18,

      bold:
        true,

      color: {
        argb:
          palette.white
      }
    };


    titleCell.fill = {
      type:
        "pattern",

      pattern:
        "solid",

      fgColor: {
        argb:
          palette.dark
      }
    };


    titleCell.alignment = {
      vertical:
        "middle",

      horizontal:
        "left"
    };


    worksheet.getRow(
      1
    ).height =
      34;


    /*
     * Metadata line
     */
    worksheet.mergeCells(
      2,
      1,
      2,
      maxColumns
    );


    const metaCell =
      worksheet.getCell(
        2,
        1
      );


    metaCell.value =
      "Generated by Vector";


    metaCell.font = {
      name:
        "Aptos",

      size:
        9,

      color: {
        argb:
          palette.muted
      }
    };


    worksheet.getRow(
      2
    ).height =
      20;


    /*
     * Small visual spacer.
     */
    worksheet.getRow(
      3
    ).height =
      7;


    const dataStartRow =
      4;


    /*
     * Add actual sheet data.
     */
    for (
      const sourceRow
      of rows
    ) {
      worksheet.addRow(
        Array.isArray(
          sourceRow
        )
          ? sourceRow
          : [
              sourceRow
            ]
      );
    }


    /*
     * Header row.
     */
    const headerRow =
      worksheet.getRow(
        dataStartRow
      );


    headerRow.height =
      25;


    for (
      let columnIndex = 1;
      columnIndex <=
        maxColumns;
      columnIndex += 1
    ) {
      const cell =
        headerRow.getCell(
          columnIndex
        );


      cell.font = {
        name:
          "Aptos",

        size:
          10,

        bold:
          true,

        color: {
          argb:
            palette.headerText
        }
      };


      cell.fill = {
        type:
          "pattern",

        pattern:
          "solid",

        fgColor: {
          argb:
            palette.header
        }
      };


      cell.alignment = {
        vertical:
          "middle",

        horizontal:
          "left",

        wrapText:
          true
      };


      cell.border = {
        bottom: {
          style:
            "medium",

          color: {
            argb:
              palette.accent
          }
        }
      };
    }


    /*
     * Data rows.
     */
    for (
      let rowIndex =
        dataStartRow + 1;
      rowIndex <=
        worksheet.rowCount;
      rowIndex += 1
    ) {
      const row =
        worksheet.getRow(
          rowIndex
        );


      row.height =
        20;


      for (
        let columnIndex = 1;
        columnIndex <=
          maxColumns;
        columnIndex += 1
      ) {
        const cell =
          row.getCell(
            columnIndex
          );


        cell.font = {
          name:
            "Aptos",

          size:
            10,

          color: {
            argb:
              palette.body
          }
        };


        cell.alignment = {
          vertical:
            "middle",

          horizontal:
            typeof cell.value ===
            "number"
              ? "right"
              : typeof cell.value ===
                  "boolean"
                ? "center"
                : "left",

          wrapText:
            true
        };


        cell.border = {
          bottom: {
            style:
              "hair",

            color: {
              argb:
                palette.border
            }
          }
        };


        if (
          (
            rowIndex -
            dataStartRow
          ) %
            2 ===
          0
        ) {
          cell.fill = {
            type:
              "pattern",

            pattern:
              "solid",

            fgColor: {
              argb:
                palette.alternate
            }
          };
        }
      }
    }


    /*
     * Intelligent widths and number formatting.
     */
    for (
      let columnIndex = 1;
      columnIndex <=
        maxColumns;
      columnIndex += 1
    ) {
      const column =
        worksheet.getColumn(
          columnIndex
        );


      let width =
        12;


      for (
        let rowIndex =
          dataStartRow;
        rowIndex <=
          worksheet.rowCount;
        rowIndex += 1
      ) {
        const value =
          worksheet.getCell(
            rowIndex,
            columnIndex
          ).value;


        let display =
          "";


        if (
          value !==
            null &&
          typeof value !==
            "undefined"
        ) {
          if (
            typeof value ===
            "object"
          ) {
            if (
              value instanceof
              Date
            ) {
              display =
                value.toISOString();
            } else {
              display =
                String(
                  value.text ||
                  value.result ||
                  value.formula ||
                  ""
                );
            }

          } else {
            display =
              String(
                value
              );
          }
        }


        width =
          Math.max(
            width,
            Math.min(
              42,
              display.length +
              2
            )
          );
      }


      column.width =
        Math.min(
          42,
          Math.max(
            12,
            width
          )
        );


      const header =
        String(
          worksheet.getCell(
            dataStartRow,
            columnIndex
          ).value ||
          ""
        ).toLowerCase();


      const numericCells =
        [];


      for (
        let rowIndex =
          dataStartRow + 1;
        rowIndex <=
          worksheet.rowCount;
        rowIndex += 1
      ) {
        const cell =
          worksheet.getCell(
            rowIndex,
            columnIndex
          );


        if (
          typeof cell.value ===
          "number"
        ) {
          numericCells.push(
            cell
          );
        }
      }


      if (
        numericCells.length >
        0
      ) {
        const integersOnly =
          numericCells.every(
            (cell) =>
              Number.isInteger(
                cell.value
              )
          );


        let format =
          integersOnly
            ? "#,##0"
            : "#,##0.00";


        if (
          /\b(percent|percentage|rate|ratio)\b/.test(
            header
          )
        ) {
          const allFractions =
            numericCells.every(
              (cell) =>
                cell.value >=
                  0 &&
                cell.value <=
                  1
            );

          if (allFractions) {
            format =
              "0.0%";
          }
        }


        if (
          /\b(chf|cost|price|budget|revenue|amount|total|value)\b/.test(
            header
          )
        ) {
          format =
            "#,##0.00";
        }


        for (
          const cell
          of numericCells
        ) {
          cell.numFmt =
            format;
        }
      }
    }


    /*
     * Freeze title area + table header.
     */
    worksheet.views = [
      {
        state:
          "frozen",

        xSplit:
          0,

        ySplit:
          dataStartRow,

        topLeftCell:
          `A${
            dataStartRow + 1
          }`,

        activeCell:
          `A${
            dataStartRow + 1
          }`
      }
    ];


    /*
     * Enable filters on the actual tabular header.
     */
    worksheet.autoFilter = {
      from: {
        row:
          dataStartRow,

        column:
          1
      },

      to: {
        row:
          dataStartRow,

        column:
          maxColumns
      }
    };


    /*
     * Print settings.
     */
    worksheet.pageSetup.orientation =
      maxColumns >
        6
        ? "landscape"
        : "portrait";


    worksheet.pageSetup.fitToPage =
      true;


    worksheet.pageSetup.fitToWidth =
      1;


    worksheet.pageSetup.fitToHeight =
      0;


    worksheet.pageSetup.margins = {
      left:
        0.35,

      right:
        0.35,

      top:
        0.55,

      bottom:
        0.55,

      header:
        0.2,

      footer:
        0.2
    };


    worksheet.headerFooter.oddFooter =
      'Generated by Vector&RPAGE &P of &N';


    worksheet.headerFooter.evenFooter =
      'Generated by Vector&RPAGE &P of &N';


    worksheet.properties.defaultRowHeight =
      19;
  }


  const bytes =
    await workbook.xlsx.writeBuffer();


  return Buffer.from(
    bytes
  );
}


async function restoreText(
  conversationId,
  value
) {
  const text =
    String(
      value ??
      ""
    );

  if (
    !conversationId ||
    !text
  ) {
    return text;
  }

  return restorePrivateValues({
    conversationId,
    text
  });
}


async function restoreSheets(
  conversationId,
  sheets
) {
  /*
   * VECTOR_XLSX_COMPLETE_ROWS_57459
   * VECTOR_XLSX_COMPLETE_COLUMNS_57459
   *
   * Preserve complete spreadsheet data during privacy restore.
   * Never silently remove rows or columns.
   */

  const maxSheets =
    Math.max(
      1,
      Math.min(
        512,
        Number(
          process.env
            .VECTOR_XLSX_MAX_SHEETS ||
          100
        )
      )
    );


  const maxRowsPerSheet =
    Math.max(
      1,
      Math.min(
        1048576,
        Number(
          process.env
            .VECTOR_XLSX_MAX_ROWS_PER_SHEET ||
          250000
        )
      )
    );


  const maxColumnsPerRow =
    Math.max(
      1,
      Math.min(
        16384,
        Number(
          process.env
            .VECTOR_XLSX_MAX_COLUMNS_PER_ROW ||
          1000
        )
      )
    );


  const sourceSheets =
    Array.isArray(
      sheets
    )
      ? sheets
      : [];


  if (
    sourceSheets.length >
    maxSheets
  ) {
    throw new Error(
      `XLSX workbook exceeds Vector's configured ${maxSheets} sheet limit. Vector will not silently truncate the workbook.`
    );
  }


  const result = [];


  for (
    let sheetIndex = 0;
    sheetIndex <
      sourceSheets.length;
    sheetIndex += 1
  ) {
    const sheet =
      sourceSheets[
        sheetIndex
      ] ||
      {};


    const restoredName =
      await restoreText(
        conversationId,
        sheet?.name ||
          `Sheet ${sheetIndex + 1}`
      );


    const restoredSheet = {
      name:
        restoredName ||
        `Sheet ${sheetIndex + 1}`,

      rows: []
    };


    const rows =
      Array.isArray(
        sheet?.rows
      )
        ? sheet.rows
        : [];


    if (
      rows.length >
      maxRowsPerSheet
    ) {
      throw new Error(
        `XLSX sheet "${restoredSheet.name}" contains ${rows.length} rows, exceeding Vector's configured ${maxRowsPerSheet} rows-per-sheet limit. Vector will not silently truncate the workbook.`
      );
    }


    for (
      let rowIndex = 0;
      rowIndex <
        rows.length;
      rowIndex += 1
    ) {
      const row =
        rows[
          rowIndex
        ];


      const values =
        Array.isArray(
          row
        )
          ? row
          : [
              row
            ];


      if (
        values.length >
        maxColumnsPerRow
      ) {
        throw new Error(
          `XLSX sheet "${restoredSheet.name}" row ${rowIndex + 1} contains ${values.length} columns, exceeding Vector's configured ${maxColumnsPerRow} columns-per-row limit. Vector will not silently truncate the workbook.`
        );
      }


      const restoredRow =
        [];


      for (
        const value
        of values
      ) {
        restoredRow.push(
          typeof value ===
            "string"
            ? await restoreText(
                conversationId,
                value
              )
            : value
        );
      }


      restoredSheet
        .rows
        .push(
          restoredRow
        );
    }


    result.push(
      restoredSheet
    );
  }


  return result;
}



/*
 * VECTOR_ARTIFACT_BINARY_SIGNATURE_57459
 *
 * Validate generated bytes before persistence.
 */
function assertArtifactBinarySignature(
  format,
  buffer
) {
  if (
    !Buffer.isBuffer(
      buffer
    ) ||
    buffer.length <
      4
  ) {
    throw new Error(
      "Generated artifact does not contain a valid file payload."
    );
  }


  if (
    format ===
    "pdf"
  ) {
    if (
      buffer
        .subarray(
          0,
          5
        )
        .toString(
          "ascii"
        ) !==
      "%PDF-"
    ) {
      throw new Error(
        "Generated PDF failed its file-signature validation."
      );
    }


    return;
  }


  if (
    format ===
      "docx" ||
    format ===
      "xlsx"
  ) {
    if (
      buffer[0] !==
        0x50 ||
      buffer[1] !==
        0x4b
    ) {
      throw new Error(
        `Generated ${format.toUpperCase()} failed its ZIP/Office file-signature validation.`
      );
    }
  }
}


export async function initializeArtifactRuntime() {
  await initializeDatabase();

  await db.query(`
    ALTER TABLE public.chat_attachments
      ADD COLUMN IF NOT EXISTS generated_by_assistant BOOLEAN NOT NULL DEFAULT FALSE;

    ALTER TABLE public.chat_attachments
      ADD COLUMN IF NOT EXISTS job_id TEXT;

    ALTER TABLE public.chat_attachments
      ADD COLUMN IF NOT EXISTS artifact_format TEXT;
  `);
}


export async function createChatArtifact({
  ownerUserId,
  conversationId,
  jobId,
  artifactPlan = null,
  format,
  filename,
  title = "",
  content = "",
  sheets = []
}) {
  await initializeArtifactRuntime();

  if (
    !ownerUserId ||
    !conversationId ||
    !jobId
  ) {
    throw new Error(
      "Artifact generation requires a user, conversation and job."
    );
  }

  const artifactFormat =
    normalizeFormat(
      format
    );

  const restoredFilename =
    await restoreText(
      conversationId,
      filename
    );

  const restoredTitle =
    await restoreText(
      conversationId,
      title
    );

  const restoredContent =
    await restoreText(
      conversationId,
      content
    );

  const restoredSheets =
    artifactFormat ===
      "xlsx"
      ? await restoreSheets(
          conversationId,
          sheets
        )
      : [];

  if (
    artifactFormat !==
      "xlsx" &&
    !String(
      restoredTitle ||
      restoredContent ||
      ""
    ).trim()
  ) {
    throw new Error(
      "PDF/DOCX artifact content is empty."
    );
  }

  let buffer;

  if (
    artifactFormat ===
    "pdf"
  ) {
    buffer =
      await createPdf({
        title:
          restoredTitle,

        content:
          restoredContent,

        artifactPlan
      });

  } else if (
    artifactFormat ===
    "docx"
  ) {
    buffer =
      await createDocx({
        title:
          restoredTitle,

        content:
          restoredContent,

        artifactPlan
      });

  } else {
    buffer =
      await createXlsx({
        title:
          restoredTitle,

        content:
          restoredContent,

        sheets:
          restoredSheets
      });
  }

  const maxBytes =
    Math.max(
      1,
      Number(
        process.env
          .VECTOR_ARTIFACT_MAX_MB ||
        25
      )
    ) *
    1024 *
    1024;

  if (
    !buffer?.length
  ) {
    throw new Error(
      "Generated artifact is empty."
    );
  }

  if (
    buffer.length >
    maxBytes
  ) {
    throw new Error(
      `Generated artifact exceeds Vector's ${Math.round(
        maxBytes /
        1024 /
        1024
      )} MB limit.`
    );
  }

    assertArtifactBinarySignature(
      artifactFormat,
      buffer
    );

  const owned =
    await db.query(
      `
        SELECT id
        FROM conversations
        WHERE
          id = $1
          AND user_id = $2
        LIMIT 1
      `,
      [
        conversationId,
        ownerUserId
      ]
    );

  if (
    owned.rowCount !==
    1
  ) {
    throw new Error(
      "Conversation ownership check failed."
    );
  }

  const id =
    crypto.randomUUID();

  const name =
    ensureFilename(
      restoredFilename,
      artifactFormat
    );

  const storageScope =
    artifactScope(
      ownerUserId
    );

  const stored =
    await writeEncryptedFile({
      projectId:
        storageScope,

      fileId:
        id,

      buffer
    });

  const result =
    await db.query(
      `
        INSERT INTO public.chat_attachments (
          id,
          owner_user_id,
          conversation_id,
          message_id,
          original_name,
          stored_name,
          storage_scope,
          mime_type,
          extension,
          size_bytes,
          sha256,
          previewable,
          encryption_version,
          generated_by_assistant,
          job_id,
          artifact_format,
          bound_at
        )
        VALUES (
          $1,$2,$3,NULL,$4,$5,$6,$7,$8,$9,$10,FALSE,1,TRUE,$11,$12,NULL
        )
        RETURNING *
      `,
      [
        id,
        ownerUserId,
        conversationId,
        name,
        stored.storedName,
        storageScope,
        MIME_TYPES[
          artifactFormat
        ],
        extensionFor(
          name
        ),
        buffer.length,
        sha256(
          buffer
        ),
        jobId,
        artifactFormat
      ]
    );

  const row =
    result.rows[
      0
    ];

  return {
    artifact: {
      id:
        row.id,

      name:
        row.original_name,

      format:
        row.artifact_format,

      mimeType:
        row.mime_type,

      sizeBytes:
        Number(
          row.size_bytes ||
          0
        ),

      downloadUrl:
        `/api/chat/attachments/${row.id}/raw`
    }
  };
}


export async function bindGeneratedArtifactsToMessage({
  ownerUserId,
  conversationId,
  jobId,
  messageId
}) {
  await initializeArtifactRuntime();

  const result =
    await db.query(
      `
        UPDATE public.chat_attachments
        SET
          message_id = $4,
          bound_at = COALESCE(
            bound_at,
            NOW()
          )
        WHERE
          owner_user_id = $1
          AND conversation_id = $2
          AND job_id = $3
          AND generated_by_assistant = TRUE
          AND message_id IS NULL
        RETURNING *
      `,
      [
        ownerUserId,
        conversationId,
        jobId,
        messageId
      ]
    );

  return result.rows.map(
    (
      row
    ) => ({
      id:
        row.id,

      name:
        row.original_name,

      format:
        row.artifact_format,

      mimeType:
        row.mime_type,

      sizeBytes:
        Number(
          row.size_bytes ||
          0
        ),

      downloadUrl:
        `/api/chat/attachments/${row.id}/raw`
    })
  );
}
